from itertools import permutations

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if not all(char in '()' for string in lst for char in string):
        return 'No'

    for perm in permutations(lst):
        new_string = ''.join(perm)
        if is_balanced(new_string):
            return 'Yes'

    return 'No'

